    let tmp = tempfile::tempdir().unwrap();
    let file = render_lora(tmp.path());
    let edge = 64u32;
    let images: Vec<Image> = (0..mlx_gen_qwen_image_2_1::MAX_REFERENCE_IMAGES as u32)
        .map(|r| Image {
            width: edge,
            height: edge,
            pixels: (0..edge * edge * 3)
