        let dst = PathBuf::from(dst);
        std::fs::create_dir_all(dst.parent().unwrap()).unwrap();
        std::fs::copy(&out.adapter_path, &dst).unwrap();
        eprintln!("[pre_epic_golden] wrote {}", dst.display());
    }
