mlx-gen-qwen-image-2-1/integration/test/training::run
fn run(
    trainer: &mut dyn Trainer,
    req: &TrainingRequest,
    mut on_step: impl FnMut(u32),
) -> (Vec<u32>, RunResult) {
    let mut steps = Vec::new();
    let out = trainer.train(req, &mut |p| {
        if let TrainingProgress::Training { step, .. } = p {
            steps.push(step);
            on_step(step);
        }
    });
    (steps, out)
}
