mlx-gen-qwen-image-2-1/integration/test/training::reference
fn reference(dir: &Path, name: &str, width: u32, height: u32, phase: u32) -> (PathBuf, Image) {
    let img = image::RgbImage::from_fn(width, height, |x, y| {
        image::Rgb([
            ((x * 3 + phase) % 256) as u8,
            ((y * 5 + phase) % 256) as u8,
            ((x * y + 3 * phase) % 256) as u8,
        ])
    });
    let path = dir.join(name);
    img.save(&path).expect("write the reference image");
    let image = Image {
        width,
        height,
        pixels: img.into_raw(),
    };
    (path, image)
}

