    let img = image::RgbImage::from_fn(width, height, |x, y| {
        image::Rgb([
            ((x * 3 + phase) % 256) as u8,
            ((y * 5 + phase) % 256) as u8,
            ((x * y + 3 * phase) % 256) as u8,
        ])
    });
