            std::fs::read(path),
            mlx_gen::gen_core::model_input_proof::read_configuration_bytes(path)
        ).unwrap_or_else(|e| panic!("{path:?}: {e}")))
            .unwrap_or_else(|e| panic!("{path:?}: {e}"));
