            .memory_strategy_contract()
            .expect("the loaded contract");
        assert_eq!(contract.provider_id, TURBO);
        assert_eq!(
            contract.asset_facts.decoder_bytes, vae_bf16_bytes,
            "{name}: the contract prices the bf16 VAE on disk"
